cat > tools/verify.py <<'EOF'
import subprocess
import sys


def git(*args: str) -> list[str]:
    return subprocess.run(["git", *args], capture_output=True, text=True).stdout.split()


def python_files(full: bool) -> list[str]:
    if full:
        return git("ls-files", "*.py")
    base = git("merge-base", "HEAD", "main")[0]
    changed = git("diff", "--name-only", base) + git("ls-files", "--others", "--exclude-standard")
    return [f for f in changed if f.endswith(".py")]


def main(full: bool = False) -> None:
    files = python_files(full)
    if not files:
        print("nothing to verify")
        return
    steps = [
        ("lint", ["flake8", "--select=F", *files]),
        ("tests", ["pytest", "-q"] if full else ["pytest", "-q", "--testmon"]),
    ]
    failed = [name for name, cmd in steps if subprocess.run(cmd).returncode != 0]
    for name, _ in steps:
        print(f"{'FAIL' if name in failed else 'pass'}  {name}")
    sys.exit(1 if failed else 0)
EOF
cat > tools/doctor.py <<'EOF'
import json
import shutil
import subprocess
import sys


def ok(*cmd: str) -> bool:
    return shutil.which(cmd[0]) is not None and subprocess.run(cmd, capture_output=True).returncode == 0


CHECKS = [  # (what, passes, how to fix)
    ("uv on PATH", lambda: ok("uv", "--version"), "install uv: https://docs.astral.sh/uv/"),
    ("Python 3.13 (uv)", lambda: ok("uv", "python", "find", "3.13"), "uv python install 3.13"),
    ("docker daemon", lambda: ok("docker", "info"), "start Docker Desktop"),
    (".venv matches uv.lock", lambda: ok("uv", "sync", "--locked", "--check"), "uv sync"),
]


def main(as_json: bool = False) -> None:
    results = [(what, passes(), fix) for what, passes, fix in CHECKS]
    for what, passed, fix in results:
        if as_json:
            print(json.dumps({"check": what, "ok": passed, "fix": fix}))
        else:
            print(f"{'ok ' if passed else 'FIX'}  {what}" + ("" if passed else f"  -> {fix}"))
    sys.exit(0 if all(passed for _, passed, _ in results) else 1)
EOF

